$(document).ready(function(){$(".alert").delay(5000).slideUp(200,function(){$(this).alert('close')});$(document).on('click','[data-toggle="lightbox"]',function(e){e.preventDefault();$(this).ekkoLightbox()});document.addEventListener('contextmenu',function(e){e.preventDefault()},!1);$('img').on('dragstart',function(e){e.preventDefault()})});function filterGallery(e){Array.from(document.getElementsByClassName('gallery-item')).forEach(t=>{t.classList.remove('show'),(e==='all'||t.classList.contains(e))&&t.classList.add('show')})}function acceptCookies(){localStorage.setItem('cookiesAccepted','true'),document.getElementById('cookie-banner').style.display='none'}window.onload=function(){localStorage.getItem('cookiesAccepted')==='true'&&(document.getElementById('cookie-banner').style.display='none')};function deleteImage(e,t){const n=`${t}`;confirm('Are you sure you want to delete this image?')&&fetch(`/delete-image/${encodeURIComponent(n)}`,{method:'POST'}).then(e=>{if(!e.ok)throw new Error('Network response was not ok');return e.json()}).then(e=>{e.success?(alert('Image deleted successfully'),window.location.reload()):alert('Error deleting image: '+e.message)}).catch(e=>{console.error('Error:',e),alert('Error deleting image: '+e.message)})}function moveImage(e){var t=e.dataset.filename.split('/'),n=t.pop(),r=`img/gallery/${e.dataset.category}/${n}`,i=`img/gallery/${e.value}/${n}`;fetch('/move-image',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:`src_public_id=${encodeURIComponent(r)}&dest_public_id=${encodeURIComponent(i)}`}).then(e=>{if(!e.ok)throw new Error(`HTTP status ${e.status}`);return e.json()}).then(e=>{e.success?(alert('Image moved successfully'),location.reload()):alert('Error moving image: '+e.message)}).catch(e=>{console.error('Error:',e),alert('Error moving image: '+e.message)})}fetch('https://www.googleapis.com/pagespeedonline/v5/runPagespeed?url=YOUR_WEBSITE_URL&key=YOUR_API_KEY').then(e=>e.json()).then(e=>{const t=e.lighthouseResult.categories.performance.score*100;document.getElementById('performance-score').innerText='Performance Score: '+t}).catch(e=>{console.error('Error:',e)});
